from itertools import product

def models(sets, statements):
    """Every Venn model: each of the 2^n regions empty or non-empty, all classes non-empty."""
    n = len(sets)
    regions = list(product([0, 1], repeat=n))[1:]           # the outside region is irrelevant
    idx = {s: i for i, s in enumerate(sets)}
    for occ in product([0, 1], repeat=len(regions)):
        live = [r for r, o in zip(regions, occ) if o]
        if all(any(r[i] for r in live) for i in range(n)) and all(st(live, idx) for st in statements):
            yield live, idx

def All(a, b):  return lambda L, I: not any(r[I[a]] and not r[I[b]] for r in L)
def Some(a, b): return lambda L, I: any(r[I[a]] and r[I[b]] for r in L)
def No(a, b):   return lambda L, I: not any(r[I[a]] and r[I[b]] for r in L)
def Not(f):     return lambda L, I: not f(L, I)

def follows(sets, statements, conclusion, possibility=False):
    ms = list(models(sets, statements))
    assert ms, "statements are inconsistent"
    hits = [conclusion(L, I) for L, I in ms]
    return any(hits) if possibility else all(hits)

def pick(found, options):
    ok = [k for k, v in options.items() if v == found]
    assert len(ok) == 1, (found, ok)
    return ok[0]

# Worked example 2024-09-09_1230_R07
S = ["fan", "brown", "chair", "plastic"]
st = [All("fan", "brown"), Some("brown", "chair"), Some("chair", "plastic")]
c = {"I": follows(S, st, Some("brown", "fan")),
     "II": follows(S, st, Some("chair", "brown")),
     "III": follows(S, st, No("chair", "plastic"))}
assert c == {"I": True, "II": True, "III": False}
opts = {"A": {"II", "III"}, "B": {"III"}, "C": set(), "D": {"I", "II"}}
assert pick({k for k, v in c.items() if v}, opts) == "D"

# 2024-09-09_0900_R21: 'All tears can never be rivers' = in every case, not all tears are rivers
S = ["tear", "drop", "stream", "river"]
st = [Some("tear", "drop"), Some("drop", "stream"), All("stream", "river")]
c = {"I": follows(S, st, Not(All("tear", "river"))),
     "II": follows(S, st, Some("drop", "river")),
     "III": follows(S, st, All("tear", "stream"), possibility=True)}
assert c == {"I": False, "II": True, "III": True}
opts = {"A": {"I"}, "B": {"II", "III"}, "C": {"III"}, "D": {"I", "II"}}
assert pick({k for k, v in c.items() if v}, opts) == "B"
